$manifest=@();$compile=@();$i=0
foreach($item in $items){$original=$item.FullPath;$chosen=$original;if($replacements.ContainsKey($item.Identity)){$chosen=Join-Path $root $replacements[$item.Identity]};$hash=(Get-FileHash $chosen).Hash;$target=Join-Path $sourceDir ((++$i).ToString('D4')+'_'+[IO.Path]::GetFileNameWithoutExtension($chosen)+'.cs');Copy-Item -LiteralPath $chosen -Destination $target;if((Get-FileHash $chosen).Hash-ne$hash){throw 'source drift'};$compile+=$target;$manifest+=@{Original=$original;OriginalHash=(Get-FileHash $original).Hash;Chosen=$chosen;Hash=$hash;Copy=$target}}
foreach($relative in $extra){$chosen=Join-Path $root $relative;$hash=(Get-FileHash $chosen).Hash;$target=Join-Path $sourceDir ((++$i).ToString('D4')+'_'+[IO.Path]::GetFileNameWithoutExtension($chosen)+'.cs');Copy-Item -LiteralPath $chosen -Destination $target;if((Get-FileHash $chosen).Hash-ne$hash){throw 'candidate drift'};$compile+=$target;$manifest+=@{Chosen=$chosen;Hash=$hash;Copy=$target}}
