foreach($n in @($project.Project.Target|Where-Object {$_.Name-eq'RunRebirthProfilerInstrumentation'})){[void]$n.ParentNode.RemoveChild($n)}
$native='C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/7DaysToDie_Data/Managed'
foreach($n in $project.SelectNodes('//HintPath')){$p=$n.InnerText.Replace('$(RebirthManagedRoot)',$native);if(!$p.Contains('$(')-and ![IO.Path]::IsPathRooted($p)){$p=[IO.Path]::GetFullPath((Join-Path $root $p))};if($p.Contains('$(')-or !(Test-Path -LiteralPath $p)){throw "unresolved reference $p"};$n.InnerText=$p}
foreach($name in @('OutDir','OutputPath','BaseOutputPath','IntermediateOutputPath','BaseIntermediateOutputPath','MSBuildProjectExtensionsPath')){foreach($n in @($project.SelectNodes("//$name"))){$n.InnerText=if($name -match 'Intermediate|Extensions'){"$run/obj/"}else{"$run/bin/"}}}
$pg=$project.CreateElement('PropertyGroup');foreach($pair in @{EnableDefaultCompileItems='false';EnableDefaultEmbeddedResourceItems='false';EnableDefaultNoneItems='false';RebirthGameRoot='C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die';RebirthManagedRoot=$native;OutDir="$run/bin/";OutputPath="$run/bin/";BaseOutputPath="$run/bin/";IntermediateOutputPath="$run/obj/";BaseIntermediateOutputPath="$run/obj/";RebirthProfilerEnableInstrumentation='false'}.GetEnumerator()){$n=$project.CreateElement($pair.Key);$n.InnerText=$pair.Value;[void]$pg.AppendChild($n)};[void]$project.Project.AppendChild($pg)
